// itself.
func fetchSpec(t *testing.T) map[string]any {
	t.Helper()
	srv := api.NewServer(api.Config{
		TestMode:    true,
		Mode:        "standalone",
		AuthBaseURL: "https://test.auth.partial.to",
		ConsoleURL:  "https://test.auth.partial.to",
	})
	h := NewHandler(srv)
	req := httptest.NewRequestWithContext(t.Context(), http.MethodGet, "/api/v1/openapi.json", nil)
	rec := httptest.NewRecorder()
	h.ServeHTTP(rec, req)
	if rec.Code != http.StatusOK {
		t.Fatalf("/api/v1/openapi.json status: got %d, want 200; body=%s", rec.Code, rec.Body.String())
	}
	var spec map[string]any
